const cfg = $('Config').first().json;
const j = $input.first().json;
const t0 = Date.now();

// Evento que envia Supabase cuando el supervisor valida o rechaza un reporte
if (j.body && j.body.record) {
  const hdr = j.headers || {};
  const rec = j.body.record;
  const old = j.body.old_record || {};
  const cambio = old.estado !== rec.estado && ['revisado', 'rechazado'].includes(rec.estado);
  if ((hdr['x-webhook-secret'] || '') !== cfg.webhook_secret || !cambio || !rec.telegram_chat_id) {
    return [{ json: { kind: 'ignorar' } }];
  }
  return [{ json: { kind: 'estado', t0, chat_id: rec.telegram_chat_id, report_id: rec.id, estado: rec.estado, comentario: rec.comentario_supervisor || '', equipo: rec.equipo || '' } }];
}

// Eventos de Telegram
const cb = j.callback_query;
const m = j.message;
const nombre = (u) => [u.first_name, u.last_name].filter(Boolean).join(' ');

if (cb) {
  return [{ json: { kind: 'callback', t0, chat_id: cb.message.chat.id, callback_id: cb.id, message_id: cb.message.message_id, data: cb.data || '', from_name: nombre(cb.from) } }];
}
if (!m) return [{ json: { kind: 'ignorar' } }];

const base = { t0, chat_id: m.chat.id, message_id: m.message_id, from_name: nombre(m.from), username: m.from.username || '' };
const replyTxt = (m.reply_to_message && (m.reply_to_message.text || m.reply_to_message.caption)) || '';
base.reply_id = (replyTxt.match(/ID:\s*([0-9a-fA-F-]{36})/) || [])[1] || '';

if (m.voice || m.audio) {
  const a = m.voice || m.audio;
  return [{ json: { ...base, kind: 'voice', file_id: a.file_id, duration: a.duration || 0 } }];
}
if (m.text) {
  if (m.text.startsWith('/')) return [{ json: { ...base, kind: 'command', command: m.text.split(/[\s@]/)[0].toLowerCase() } }];
  return [{ json: { ...base, kind: 'text', text: m.text } }];
}
return [{ json: { ...base, kind: 'command', command: '/no_soportado' } }];

const cfg = $('Config').first().json;
const ctx = $input.first().json;
if (['estado', 'ignorar'].includes(ctx.kind) || !cfg.require_whitelist) {
  return [{ json: { ...ctx, authorized: true } }];
}
try {
  const r = await this.helpers.httpRequest({
    method: 'GET',
    url: `${cfg.supabase_url}/rest/v1/usuarios_telegram?chat_id=eq.${ctx.chat_id}&activo=eq.true&select=chat_id,nombre`,
    headers: { apikey: cfg.supabase_key, Authorization: `Bearer ${cfg.supabase_key}` },
    json: true,
  });
  const ok = Array.isArray(r) && r.length > 0;
  return [{ json: { ...ctx, authorized: ok, tecnico_registrado: ok ? r[0].nombre : null } }];
} catch (e) {
  return [{ json: { ...ctx, authorized: false } }];
}

const c = $input.first().json;
let text;
if (c.command === '/no_soportado') {
  text = '⚠️ Solo puedo procesar <b>audios</b> y <b>mensajes de texto</b>.';
} else {
  text = `👷 <b>MaintAI</b> · asistente de reportes de mantenimiento\n\nEnvíame un <b>audio</b> o un <b>mensaje de texto</b> contando lo que hiciste: equipo, falla, actividades y repuestos usados.\n\nLuego revisa el resumen y pulsa ✅ <b>Confirmar</b> o ✏️ <b>Corregir</b>.\n\nTu chat ID: <code>${c.chat_id}</code>`;
}
return [{ json: { tg_method: 'sendMessage', tg: { chat_id: c.chat_id, parse_mode: 'HTML', text } } }];

const ctx = $('Verificar autorizacion').first().json;
const j = $input.first().json;
const texto = String(ctx.kind === 'voice' ? (j.text || '') : (ctx.text || '')).trim();
return [{ json: { ...ctx, texto } }];

const SYSTEM = "Eres un asistente de mantenimiento industrial de una central termica de cogeneracion (turbinas de vapor, calderas, BMS, sistemas DCS Honeywell, tableros electricos, subestaciones SE-1 y SE-2, recuperacion de condensados RCO). Recibes el relato de un tecnico (puede venir de una transcripcion de audio con errores) y devuelves UNICAMENTE un objeto JSON con estas claves:\nequipo (string|null), codigo_equipo (string|null, p. ej. P-101A), area (string|null), tipo_mantenimiento ('preventivo'|'correctivo'|'predictivo'|'inspeccion'|'otro'|null), falla (string|null: sintoma o anomalia observada), causa_probable (string|null), actividades (array de strings, una accion por elemento, en infinitivo o pasado), repuestos (array de {nombre, cantidad (number|null), codigo (string|null)}), prioridad ('baja'|'media'|'alta'|'critica'|null), numero_ot (string|null), fecha_intervencion ('YYYY-MM-DD'|null), duracion_minutos (integer|null), observaciones (string|null), confianza (number entre 0 y 1: tu certeza global de la extraccion).\nReglas: no inventes datos; si algo no se menciona usa null o []. Conserva codigos de equipo, numeros de serie y OT tal como se dicen. Corrige errores evidentes de transcripcion de terminos tecnicos. Interpreta fechas relativas (ayer, hoy) con la fecha actual indicada. Responde solo el JSON, sin texto adicional.";
const cfg = $('Config').first().json;
const ctx = $('Preparar texto').first().json;
let orig = null;
if (ctx.reply_id) {
  try { const o = $('Obtener reporte original').first().json; if (o && o.id) orig = o; } catch (e) {}
}
const hoy = new Date().toLocaleDateString('en-CA', { timeZone: cfg.timezone || 'America/Lima' });
const system = SYSTEM + `\nFecha actual: ${hoy}.`;
let user;
if (orig) {
  const actual = {
    equipo: orig.equipo, codigo_equipo: orig.codigo_equipo, area: orig.area, tipo_mantenimiento: orig.tipo_mantenimiento,
    falla: orig.falla, causa_probable: orig.causa_probable, actividades: orig.actividades, repuestos: orig.repuestos,
    prioridad: orig.prioridad, numero_ot: orig.numero_ot, fecha_intervencion: orig.fecha_intervencion,
    duracion_minutos: orig.duracion_minutos, observaciones: orig.observaciones,
  };
  user = `REPORTE ACTUAL (JSON):\n${JSON.stringify(actual)}\n\nRELATO ORIGINAL DEL TECNICO:\n${orig.texto_original || ''}\n\nCORRECCION DEL TECNICO:\n${ctx.texto}\n\nAplica la correccion sobre el reporte actual y devuelve el JSON completo actualizado.`;
} else {
  user = `RELATO DEL TECNICO:\n${ctx.texto}`;
}
return [{ json: { ...ctx, orig_id: orig ? orig.id : null, orig_correcciones: orig ? (orig.correcciones || 0) : 0, llm_body: { model: cfg.llm_model, temperature: 0, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] } } }];

const ctx = $('Armar prompt').first().json;
const resp = $input.first().json;
let d = {};
try { d = JSON.parse(resp.choices[0].message.content); } catch (e) { d = {}; }

const s = (v) => (v === null || v === undefined || String(v).trim() === '') ? null : String(v).trim();
const num = (v) => (v === null || v === undefined || v === '') ? null : (Number.isFinite(Number(v)) ? Number(v) : null);
const arr = (v) => Array.isArray(v) ? v.map((x) => String(x).trim()).filter(Boolean) : [];
const pick = (v, list) => { const x = String(v || '').toLowerCase().trim(); return list.includes(x) ? x : null; };

const repuestos = (Array.isArray(d.repuestos) ? d.repuestos : [])
  .map((r) => typeof r === 'string' ? { nombre: s(r), cantidad: null, codigo: null } : { nombre: s(r && r.nombre), cantidad: num(r && r.cantidad), codigo: s(r && r.codigo) })
  .filter((r) => r.nombre);
const dur = num(d.duracion_minutos);
const conf = num(d.confianza);

const campos = {
  equipo: s(d.equipo), codigo_equipo: s(d.codigo_equipo), area: s(d.area),
  tipo_mantenimiento: pick(d.tipo_mantenimiento, ['preventivo', 'correctivo', 'predictivo', 'inspeccion', 'otro']),
  falla: s(d.falla), causa_probable: s(d.causa_probable),
  actividades: arr(d.actividades), repuestos,
  prioridad: pick(d.prioridad, ['baja', 'media', 'alta', 'critica']),
  numero_ot: s(d.numero_ot),
  fecha_intervencion: /^\d{4}-\d{2}-\d{2}$/.test(String(d.fecha_intervencion || '')) ? d.fecha_intervencion : null,
  duracion_minutos: dur === null ? null : Math.max(0, Math.round(dur)),
  observaciones: s(d.observaciones),
  confianza: conf === null ? null : Math.min(1, Math.max(0, conf)),
};
const faltantes = [];
if (!campos.equipo) faltantes.push('equipo');
if (!campos.falla) faltantes.push('falla');
if (!campos.actividades.length) faltantes.push('actividades');

const ms = Date.now() - (ctx.t0 || Date.now());
let mode, db_row;
if (ctx.orig_id) {
  mode = 'update';
  db_row = { ...campos, campos_faltantes: faltantes, raw_ia: d, texto_correccion: ctx.texto, estado: 'corregido', correcciones: (ctx.orig_correcciones || 0) + 1, tiempo_procesamiento_ms: ms };
} else {
  mode = 'new';
  db_row = {
    telegram_chat_id: ctx.chat_id, telegram_message_id: ctx.message_id,
    tecnico_nombre: ctx.tecnico_registrado || ctx.from_name, tecnico_username: ctx.username || null,
    origen: ctx.kind === 'voice' ? 'audio' : 'texto', audio_duracion_seg: ctx.kind === 'voice' ? ctx.duration : null,
    texto_original: ctx.texto, ...campos, campos_faltantes: faltantes, raw_ia: d, estado: 'pendiente', tiempo_procesamiento_ms: ms,
  };
}
return [{ json: { ...ctx, mode, db_row } }];

const esc = (t) => String(t === null || t === undefined ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const r = $input.first().json;
const p = $('Procesar respuesta IA').first().json;
const L = [];
L.push(`📋 <b>Reporte de mantenimiento</b>${p.mode === 'update' ? ' · corregido' : ''}`, '');
L.push(`🔧 <b>Equipo:</b> ${esc(r.equipo || '—')}${r.codigo_equipo ? ' (' + esc(r.codigo_equipo) + ')' : ''}`);
if (r.area) L.push(`📍 <b>Área:</b> ${esc(r.area)}`);
L.push(`⚠️ <b>Falla:</b> ${esc(r.falla || '—')}`);
if (r.causa_probable) L.push(`🔍 <b>Causa probable:</b> ${esc(r.causa_probable)}`);
L.push('🛠 <b>Actividades:</b>');
const acts = r.actividades || [];
if (acts.length) acts.forEach((a) => L.push('  • ' + esc(a))); else L.push('  —');
L.push('🔩 <b>Repuestos:</b>');
const reps = r.repuestos || [];
if (reps.length) reps.forEach((x) => L.push('  • ' + esc(x.nombre) + (x.cantidad ? ' x' + esc(x.cantidad) : '') + (x.codigo ? ' (' + esc(x.codigo) + ')' : ''))); else L.push('  —');
const meta = [];
if (r.tipo_mantenimiento) meta.push(esc(r.tipo_mantenimiento));
if (r.prioridad) meta.push('prioridad ' + esc(r.prioridad));
if (r.duracion_minutos !== null && r.duracion_minutos !== undefined) meta.push(esc(r.duracion_minutos) + ' min');
if (r.numero_ot) meta.push('OT ' + esc(r.numero_ot));
if (r.fecha_intervencion) meta.push(esc(r.fecha_intervencion));
if (meta.length) L.push('', '🏷 ' + meta.join(' · '));
const falt = r.campos_faltantes || [];
if (falt.length) L.push('', `❗ <b>Faltan datos:</b> ${esc(falt.join(', '))}. Pulsa ✏️ Corregir para completarlos.`);
L.push('', '¿Es correcto?', `ID: <code>${esc(r.id)}</code>`);
return [{ json: { tg_method: 'sendMessage', tg: {
  chat_id: p.chat_id, parse_mode: 'HTML', text: L.join('\n'),
  reply_markup: { inline_keyboard: [[{ text: '✅ Confirmar', callback_data: 'ok:' + r.id }, { text: '✏️ Corregir', callback_data: 'ed:' + r.id }]] },
} } }];

const c = $input.first().json;
const m = String(c.data || '').match(/^(ok|ed):([0-9a-fA-F-]{36})$/);
return [{ json: { ...c, action: m ? m[1] : 'otro', report_id: m ? m[2] : null } }];

const c = $('Interpretar boton').first().json;
return [
  { json: { tg_method: 'answerCallbackQuery', tg: { callback_query_id: c.callback_id, text: 'Reporte confirmado ✅' } } },
  { json: { tg_method: 'editMessageReplyMarkup', tg: { chat_id: c.chat_id, message_id: c.message_id, reply_markup: { inline_keyboard: [] } } } },
  { json: { tg_method: 'sendMessage', tg: { chat_id: c.chat_id, parse_mode: 'HTML', text: '✅ <b>Reporte confirmado</b> y enviado a supervisión.' } } },
];

const c = $('Interpretar boton').first().json;
return [
  { json: { tg_method: 'answerCallbackQuery', tg: { callback_query_id: c.callback_id } } },
  { json: { tg_method: 'sendMessage', tg: {
    chat_id: c.chat_id, parse_mode: 'HTML',
    text: `✏️ Responde a <b>este mensaje</b> con la corrección (texto o audio).\nEjemplo: «el equipo es la bomba P-101A, no la P-101B».\n\nID: ${c.report_id}`,
    reply_markup: { force_reply: true, input_field_placeholder: 'Escribe o graba la corrección…' },
  } } },
];

const esc = (t) => String(t === null || t === undefined ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const c = $input.first().json;
const eq = c.equipo ? ` de <b>${esc(c.equipo)}</b>` : '';
let text;
if (c.estado === 'revisado') {
  text = `✅ Tu reporte${eq} fue <b>validado</b> por supervisión.`;
  if (c.comentario) text += `\nComentario: ${esc(c.comentario)}`;
} else {
  text = `❌ Tu reporte${eq} fue <b>rechazado</b> por supervisión.`;
  if (c.comentario) text += `\nMotivo: ${esc(c.comentario)}`;
}
return [{ json: { tg_method: 'sendMessage', tg: { chat_id: c.chat_id, parse_mode: 'HTML', text } } }];

let ctx = {};
try { ctx = $('Normalizar').first().json; } catch (e) {}
if (!ctx.chat_id) return [];
return [{ json: { tg_method: 'sendMessage', tg: { chat_id: ctx.chat_id, parse_mode: 'HTML', text: '⚠️ No pude procesar tu mensaje. Inténtalo de nuevo o envíalo como texto. Si persiste, avisa a tu supervisor.' } } }];
